<script setup>
import { computed, ref } from 'vue'
const props = defineProps({ stats: Object, busy: Boolean })
defineEmits(['refresh', 'detail'])
const filter = ref('all')
const pct = value => value == null ? '—' : `${(value * 100).toFixed(1)}%`
const num = value => value == null ? '—' : Number(value.toFixed(1)).toLocaleString('zh-CN')
const reflections = computed(() => (props.stats?.reflections ?? []).filter(r => filter.value === 'all' || (filter.value === 'empty' ? r.chars === 0 : r.analysis.score < 6)))
const maxCount = computed(() => Math.max(1, ...(props.stats?.distribution ?? []).map(d => d.count)))
</script>
<template>
  <section class="teaching-statistics">
    <div class="card round-bar"><div><h2>本轮教学统计</h2><p class="muted">仅统计本轮全部已提交学生的最终结果，不随学号搜索变化。未提交学生不计零分。</p></div><div class="actions"><button :disabled="busy" @click="$emit('refresh')">刷新</button><a v-if="stats" class="button" href="/api/teacher/statistics.csv">导出本轮统计 CSV</a><a v-if="stats" class="button" href="/api/teacher/export.csv">导出学生成绩 CSV</a></div></div>
    <p v-if="!stats" class="card empty">还没有开始实训，请先在“本轮成绩”开始第一轮。</p>
    <p v-else-if="!stats.count" class="card empty">本轮暂无提交。学生提交后点击刷新查看统计。</p>
    <template v-else>
      <div class="stats-overview"><div class="card"><span>已提交</span><strong>{{ stats.count }} 人</strong></div><div class="card"><span>平均总分</span><strong>{{ num(stats.averageScore) }}</strong></div><div class="card"><span>平均分类正确率</span><strong>{{ pct(stats.averageAccuracy) }}</strong></div><div class="card"><span>优化达标人数占比</span><strong>{{ pct(stats.tasks[2].rate) }}</strong></div></div>
      <section class="card"><h3>任务完成与达成情况</h3><div class="table-scroll"><table><thead><tr><th>任务点</th><th>达成标准</th><th>达成人数 / 参与人数</th><th>达成率</th></tr></thead><tbody><tr v-for="task in stats.tasks" :key="task.label"><td>{{ task.label }}</td><td>{{ task.criterion }}</td><td>{{ task.participants ? `${task.achieved} / ${task.participants}` : '无参与数据' }}</td><td>{{ pct(task.rate) }}</td></tr></tbody></table></div><p class="muted">最终容量违规数：{{ stats.capacityViolations ?? '无数据' }}（{{ stats.capacityParticipants }} 人有记录）。系统阻止不合法方案提交；这不代表操作过程中没有违规。历史版本未参加的任务不计入分母。</p></section>
      <div class="stats-charts">
        <section class="card"><h3>各商品分类错误率</h3><p class="muted">按错误率从高到低排列 · 错误人数 / 参与人数</p><div v-for="p in stats.products" :key="p.sku" class="stats-bar-row"><div class="stats-bar-label"><span>{{ p.sku }} {{ p.name }} · 正确类别 {{ p.correctClass }}</span><strong>{{ p.errors }}/{{ p.participants }} · {{ pct(p.errorRate) }}</strong></div><div class="stats-track" aria-hidden="true"><div class="stats-fill stats-error" :style="{ width: `${(p.errorRate ?? 0) * 100}%` }"></div></div></div></section>
        <section class="card"><h3>储位优化改善率分布</h3><p>平均改善率 <strong>{{ pct(stats.averageImprovement) }}</strong> · 本轮满分线 {{ pct(stats.threshold) }}</p><p class="muted">平均模拟拣货成本：{{ num(stats.averageBaselineCost) }} → {{ num(stats.averageCurrentCost) }} {{ stats.costUnit }}</p><div class="stats-columns"><div v-for="d in stats.distribution" :key="d.label" class="stats-column"><strong>{{ d.count }} 人</strong><div class="stats-column-track" aria-hidden="true"><div :style="{ height: `${d.count / maxCount * 100}%` }"></div></div><span>{{ d.label }}</span></div></div><p class="muted">展示实际改善率，负值表示成本增加。v3成本包含周转量与层高惩罚，并非实际行走距离。</p></section>
      </div>
      <section class="card"><h3>单据审核：各字段错误识别情况</h3><p v-if="!stats.reviewParticipants" class="muted">无参与数据（历史版本未参加）</p><template v-else><p>参与 {{ stats.reviewParticipants }} 人 · 正确标注 {{ stats.reviewTotals.correctMarks }} 次（人均 {{ num(stats.reviewTotals.correctMarks / stats.reviewParticipants) }}） · 误标 {{ stats.reviewTotals.wrongMarks }} 次（人均 {{ num(stats.reviewTotals.wrongMarks / stats.reviewParticipants) }}） · 漏标 {{ stats.reviewTotals.missedMarks }} 次（人均 {{ num(stats.reviewTotals.missedMarks / stats.reviewParticipants) }}）</p><p class="muted">绿色为正确标注，橙色为漏标；识别率以该字段实际错误数为分母，误标单独统计。</p><div v-for="f in stats.fields" :key="f.fieldKey" class="stats-bar-row"><div class="stats-bar-label"><strong>{{ f.label }}</strong><span>{{ f.errors ? `正确标注 ${f.correct}/${f.errors} · 识别率 ${pct(f.recognitionRate)} · 漏标 ${f.missed}` : '未出题' }} · 误标 {{ f.wrong }}</span></div><div class="stats-track stats-stack" aria-hidden="true"><div class="stats-fill" :style="{ width: `${(f.recognitionRate ?? 0) * 100}%` }"></div><div class="stats-fill stats-missed" :style="{ width: `${f.errors ? f.missed / f.errors * 100 : 0}%` }"></div></div></div></template></section>
      <section class="card"><h3>反思说明</h3><p>已填写 {{ stats.reflectionFilled }}/{{ stats.count }} 人 · 量表达标（原始分≥6/10）{{ stats.tasks[4].achieved }}/{{ stats.count }} 人</p><p class="muted">自动评分量表：篇幅2分、摆放依据3分、变化调整3分、容量与安全约束1分、因果表达1分。关键词只是判断证据，教师仍需阅读内容质量。</p><label>筛选反思<select v-model="filter"><option value="all">全部</option><option value="empty">未填写</option><option value="short">量表未达标（含未填写）</option></select></label><div class="table-scroll"><table><thead><tr><th>学生</th><th>字数</th><th>原始分</th><th>分项（篇幅/依据/调整/约束/因果）</th><th>反思说明</th><th>操作</th></tr></thead><tbody><tr v-for="r in reflections" :key="r.id"><td>{{ r.studentId }} {{ r.studentName }}</td><td>{{ r.chars }}</td><td>{{ r.analysis.score }}/10</td><td>{{ r.analysis.breakdown.length }}/{{ r.analysis.breakdown.placementReason }}/{{ r.analysis.breakdown.adjustment }}/{{ r.analysis.breakdown.constraints }}/{{ r.analysis.breakdown.causal }}</td><td class="stats-reflection"><details v-if="r.text"><summary>{{ Array.from(r.text).slice(0, 50).join('') }}{{ r.chars > 50 ? '…' : '' }}</summary><p class="preserve">{{ r.text }}</p><p v-if="r.analysis.missing.length" class="muted">可补充：{{ r.analysis.missing.join('；') }}</p></details><span v-else>未填写</span></td><td><button :disabled="busy" @click="$emit('detail', r.id)">详情</button></td></tr><tr v-if="!reflections.length"><td colspan="6" class="empty">没有符合条件的反思。</td></tr></tbody></table></div></section>
    </template>
  </section>
</template>
